// An absent protobuf bytes field decodes to an empty Uint8Array, so "is this real payload" is a
// length test as much as a type test; the log helpers spell out the two shapes used everywhere.
const isBytes = (v) => v instanceof Uint8Array && v.length > 0;
const byteLen = (v) => (isBytes(v) ? v.length + ' bytes' : 'null');

// The per-frame logs all want the same shape. Keeping the DEBUG test inside means callers do not
// have to guard the cost of building the preview array themselves.
function dbgFrame(what, data, preview) {
  if (!DEBUG) {
    return;
  }
  const head = Array.from(data.slice(0, preview === undefined ? 20 : preview));
  dbg('[WebBridge] ' + what + ', bytes=', data.length, 'first:', head);
}

