// Same shape as the native auto id on Android/iOS: a random 10-digit number. The browser
// has no MAC address to derive one from, and a clock-derived id collides between clients
// that start in the same second.
function generateId() {
  const r = crypto.getRandomValues(new Uint32Array(1))[0];
  return String(1000000000 + (r % 1000000000));
}

function generateUuid() {
  if (crypto.randomUUID) return crypto.randomUUID();
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const h = bytesToHex(b);
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

function bytesToHex(bytes) {
  return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
}

function hexToBytes(hex) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
  return bytes;
}

let _keyReady = null;

async function generateKeyPair() {
  try {
    const kp = await crypto.subtle.generateKey({ name: 'Ed25519' }, true, ['sign', 'verify']);
    const raw = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));
    const jwk = await crypto.subtle.exportKey('jwk', kp.privateKey);
    localStorage.setItem('pk', bytesToHex(raw));
    localStorage.setItem('sk_jwk', JSON.stringify(jwk));
  } catch(e) {
    // crypto.subtle only has Ed25519 in recent Chrome. Storing 32 random bytes as the public
    // key used to register an id bound to a key that can never sign anything, and the failure
    // only surfaced much later as a handshake timeout. Leave pk unset: the RegisterPeerResponse
    // handler already skips RegisterPk when getPkBytes() comes back empty.
    console.warn('[WebBridge] Ed25519 unavailable, not registering a key:', e);
    localStorage.removeItem('pk');
  }
}

