// varint, so file_num 1 comes back as 2 unless it is folded back here. Written with
// division rather than >>> so a sint64 outside the 32-bit range still decodes.
function fromZigzag(v) {
  const n = Number(v) || 0;
  return (n % 2 === 0) ? n / 2 : -(n + 1) / 2;
}

